import{_ as o,o as t,c as r,a2 as s}from"./chunks/framework.CqdVOxXJ.js";const n="/rakkii-cars-guide/screenshots/v2/b02-time-clock.png",a="/rakkii-cars-guide/screenshots/v2/c06-leave-request.png",i="/rakkii-cars-guide/screenshots/v2/c07-payslip.png",m=JSON.parse('{"title":"Me hub: clock, leave, overtime, payslip","description":"","frontmatter":{},"headers":[],"relativePath":"me/index.md","filePath":"me/index.md","lastUpdated":1794621279000}'),l={name:"me/index.md"};function d(p,e,c,h,g,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="me-hub-clock-leave-overtime-payslip" tabindex="-1">Me hub: clock, leave, overtime, payslip <a class="header-anchor" href="#me-hub-clock-leave-overtime-payslip" aria-label="Permalink to &quot;Me hub: clock, leave, overtime, payslip&quot;">​</a></h1><p><strong>For:</strong> Everyone with a login · <strong>Hub:</strong> Me</p><p>The <strong>Me</strong> hub is about you only: your time, your leave and your pay. Nobody else&#39;s data shows here.</p><table tabindex="0"><thead><tr><th>Page</th><th>Use it to</th></tr></thead><tbody><tr><td><strong>Time clock</strong></td><td>Clock in and out, and see today&#39;s punches</td></tr><tr><td><strong>Leave</strong></td><td>Ask for leave and see your balances</td></tr><tr><td><strong>My overtime</strong></td><td>File overtime</td></tr><tr><td><strong>My payslip</strong></td><td>See your payslips</td></tr><tr><td><strong>My commission</strong></td><td>See your commission (only if you have some)</td></tr><tr><td><strong>My incentive</strong></td><td>See your quarterly target (sales)</td></tr><tr><td><strong>My profile</strong></td><td>See your employee record, documents and scorecards</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Owners</p><p>Owners don&#39;t clock in or file leave or overtime. Their Me hub has <strong>My payslip</strong> and <strong>My profile</strong> only.</p></div><p>To open the Me hub, press the hub name in the top bar (for example <strong>Workshop ▾</strong>) and choose <strong>Me</strong>.</p><h2 id="clock-in-and-out" tabindex="-1">Clock in and out <a class="header-anchor" href="#clock-in-and-out" aria-label="Permalink to &quot;Clock in and out&quot;">​</a></h2><ol><li>Open <strong>Me › Time clock</strong> (technicians can also press <strong>Clock in</strong> on <strong>My jobs</strong>).</li><li>Take the photo if the shop asks for one.</li><li>Press <strong>Clock in</strong>. At the end of the day, press <strong>Clock out</strong>.</li><li>Check your punch under <strong>Today</strong>.</li></ol><p><img src="'+n+'" alt="Time clock"></p><ul><li><strong>Away from the shop?</strong> Type a reason when the app asks. The punch stays <strong>Pending</strong> until the owner approves it, and pending time isn&#39;t paid yet.</li><li><strong>Forgot to clock out?</strong> Tell the owner. They can close the punch with the real time.</li></ul><h2 id="ask-for-leave" tabindex="-1">Ask for leave <a class="header-anchor" href="#ask-for-leave" aria-label="Permalink to &quot;Ask for leave&quot;">​</a></h2><ol><li>Open <strong>Me › Leave</strong>. Your balances are at the top.</li><li>Press <strong>Request leave</strong>.</li><li>Choose the <strong>Type</strong> (Vacation, Sick, Unpaid or Service incentive leave).</li><li>Pick the <strong>Start date</strong> and <strong>End date</strong>. For half a day, pick the same date for both, then set <strong>Half day</strong> to <strong>Morning (AM)</strong> or <strong>Afternoon (PM)</strong>.</li><li>Add a <strong>Note (optional)</strong> and press <strong>Request</strong>.</li></ol><p><img src="'+a+'" alt="Request leave dialog"></p><p>Your request shows under <strong>My requests</strong> as <strong>Pending</strong> until the owner decides. You can cancel it until then. If you have cars due while you&#39;re away, tell the desk: the owner sees your open jobs when approving your leave and can hand them to someone else.</p><h2 id="file-overtime" tabindex="-1">File overtime <a class="header-anchor" href="#file-overtime" aria-label="Permalink to &quot;File overtime&quot;">​</a></h2><ol><li>Open <strong>Me › My overtime</strong>.</li><li>Press <strong>Request OT</strong>.</li><li>Enter the <strong>Date</strong>, <strong>Hours</strong> and a <strong>Reason</strong>, then press <strong>File request</strong>.</li></ol><p>Overtime is paid only once approved, and never for more hours than you actually punched.</p><h2 id="see-your-payslip" tabindex="-1">See your payslip <a class="header-anchor" href="#see-your-payslip" aria-label="Permalink to &quot;See your payslip&quot;">​</a></h2><ol><li>Open <strong>Me › My payslip</strong>.</li><li>Pick a period to see the pay, deductions and <strong>Net</strong>.</li><li>Press <strong>Print</strong> for a copy.</li></ol><p>Payslips appear only after the owner locks that payroll.</p><p><img src="'+i+'" alt="My payslip"></p><h2 id="my-profile" tabindex="-1">My profile <a class="header-anchor" href="#my-profile" aria-label="Permalink to &quot;My profile&quot;">​</a></h2><p>Your employee record, documents (press <strong>Download</strong> for a copy) and finalized scorecards. To fix a mistake in your details, ask the owner.</p>',23)])])}const k=o(l,[["render",d]]);export{m as __pageData,k as default};
